    }

    if (config.reasoningEfforts.length === 0) {
      return [{name: config.name, reasoningEffort: 'medium'}]
    }

    return config.reasoningEfforts.map(effort => {
      return {name: config.name, reasoningEffort: effort}
    })
  }) as Array<ModelVariant<Model>>
}

